        for y in range(1, 15):
            # b^{p-1} + a = p^y and a <= b
            # p^y - b^{p-1} = a <= b
            # p^y <= b^{p-1} + b
            # So b >= (p^y - b)^{1/(p-1)}
            # This means b is around p^{y/(p-1)}
            b_approx = int(p**(y / (p - 1)))
