def check(p, a, b):
    if p <= 2: return False
    if a <= 0 or b <= 0: return False
    if a > b: return False

    val1 = a**(p-1) + b
    val2 = b**(p-1) + a

    def is_power(n, base):
        if n == 1: return True
        while n > 1:
            if n % base != 0:
                return False
            n //= base
        return True

    return is_power(val1, p) and is_power(val2, p)

